def prevFixed {α : Type u} [CompleteLattice α] (f : α →o α) (x : α) (hx : f x ≤ x) : ↑(Function.fixedPoints ⇑f) :=
  let down_x := { y : α // y ≤ x }
  let f_down : down_x → down_x := fun y => ⟨f y.val, le_trans (f.mono y.2) hx⟩
  let f_down_order_hom : down_x →o down_x := ⟨f_down, fun y z h => f.mono h⟩
  let gfp_down := OrderHom.gfp f_down_order_hom
  ⟨gfp_down.val, by rw [OrderHom.gfp_eq f_down_order_hom]⟩
